 JOIN pg_policy p ON p.polrelid=to_regclass(required.relation_name) AND p.polname=required.policy_name)='[{"name":"final_internal_writer","check":"true","roles":["selqiro_listing_final_writer_v1"],"using":"true","command":"*","relation":"listing_publication_private.attempts","permissive":true},{"name":"final_internal_writer","check":"true","roles":["selqiro_listing_final_writer_v1"],"using":"true","command":"*","relation":"listing_publication_private.cleanup","permissive":true},{"name":"multipart_attempt_internal","check":"true","roles":["selqiro_listing_final_writer_v1"],"using":"true","command":"*","relation":"listing_publication_private.multipart_attempts","permissive":true},{"name":"multipart_auxiliary_internal","check":null,"roles":["selqiro_listing_final_writer_v1"],"using":"true","command":"r","relation":"listing_publication_private.multipart_auxiliary_receipts","permissive":true},{"name":"multipart_session_internal","check":"true","roles":["selqiro_listing_final_writer_v1"],"using":"true","command":"*","relation":"listing_publication_private.multipart_sessions","permissive":true},{"name":"final_internal_writer","check":"true","roles":["selqiro_listing_final_writer_v1"],"using":"true","command":"*","relation":"listing_publication_private.objects","permissive":true},{"name":"final_internal_writer","check":"true","roles":["selqiro_listing_final_writer_v1"],"using":"true","command":"*","relation":"listing_publication_private.publications","permissive":true},{"name":"final_internal_writer","check":"true","roles":["selqiro_listing_final_writer_v1"],"using":"true","command":"*","relation":"listing_publication_private.slots","permissive":true},{"name":"final_internal_writer","check":"true","roles":["selqiro_listing_final_writer_v1"],"using":"true","command":"*","relation":"listing_publication_private.web_images","permissive":true},{"name":"final_writer_images","check":"(EXISTS ( SELECT 1\n   FROM public.listings l\n  WHERE ((l.id = listing_images.listing_id) AND public.current_user_has_identity_access(l.identity_id))))","roles":["selqiro_listing_final_writer_v1"],"using":"(EXISTS ( SELECT 1\n   FROM public.listings l\n  WHERE ((l.id = listing_images.listing_id) AND public.current_user_has_identity_access(l.identity_id))))","command":"*","relation":"public.listing_images","permissive":true},{"name":"final_writer_listings","check":"public.current_user_has_identity_access(identity_id)","roles":["selqiro_listing_final_writer_v1"],"using":"public.current_user_has_identity_access(identity_id)","command":"*","relation":"public.listings","permissive":true}]'::jsonb AS final_writer_policies,
  EXISTS(SELECT 1 FROM hosted WHERE context->>'project_ref'='vyjletlmwoiwxsnsunlm'
   AND context->>'release_id'='listing-publication-hosted-preview-v1' AND (context->>'release_ready')::boolean
   AND context->>'storage_authority_version'='source-part-rfc3986-v1'
   AND context->>'instance_id'='2d088814-0900-448a-a9d1-7b05470cb1d2')
   AND listing_publication_private.hosted_storage_contract_ready() AS hosted_context_ready,
  capability='69aa02276538a94d25dacfa075b2792ec393fc0816fcf30a7f354ef8e3de37cd' AND (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
   WHERE n.nspname||'.'||p.proname=ANY(ARRAY['listing_publication_private.hosted_completed_source_deleted_v1','public.claim_listing_published_source_cleanup_v1','public.record_listing_published_source_cleanup_v1','listing_publication_private.multipart_object_fully_deleted']::text[]))=1
   AND NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
    WHERE n.nspname||'.'||p.proname=ANY(ARRAY['listing_publication_private.hosted_completed_source_deleted_v1','public.claim_listing_published_source_cleanup_v1','public.record_listing_published_source_cleanup_v1']::text[])) AS capability_absent,
  capability='cbd582d9cd263ecd166220f6200f4cc9eed27818a3ef53d9aa9827f6f422ae89' AND (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
   WHERE n.nspname||'.'||p.proname=ANY(ARRAY['listing_publication_private.hosted_completed_source_deleted_v1','public.claim_listing_published_source_cleanup_v1','public.record_listing_published_source_cleanup_v1','listing_publication_private.multipart_object_fully_deleted']::text[]))=4 AS capability_present
 FROM measured),
 assessed AS (SELECT *,coalesce(functions AND installer AND actor_roles AND closed_private_schema AND core_relations
  AND required_columns AND managed_triggers AND final_writer_policies AND hosted_context_ready,false) dependencies_ok FROM checks),
 result_row AS (SELECT jsonb_build_object('schema_version',1,'kind','listing-hosted-completed-source-cleanup-v1',
  'state',CASE WHEN dependencies_ok AND capability_absent AND NOT capability_present THEN 'absent'
   WHEN dependencies_ok AND capability_present AND NOT capability_absent THEN 'applied' ELSE 'unknown' END,
  'recognized',dependencies_ok AND (capability_absent<>capability_present),
  'ready_to_apply',dependencies_ok AND capability_absent AND NOT capability_present,'dependencies_ok',dependencies_ok,
  'capability_absent',capability_absent,'capability_present',capability_present,
  'guards',to_jsonb(assessed)-ARRAY['dependencies_ok','capability_absent','capability_present'],
  'hosted_context',(SELECT context FROM hosted),
  'fingerprints',jsonb_build_object('dependencies',dependencies,'capability',capability),
  'invariants',jsonb_build_object('existing_functions',existing_functions,'existing_authority',existing_authority,'immutable_structure',immutable_structure)) result
 FROM assessed CROSS JOIN measured)
 SELECT result FROM result_row;
DO $before$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM hosted_source_install_before WHERE result->>'state'='absent' AND (result->>'ready_to_apply')::boolean) THEN
  RAISE EXCEPTION 'LISTING_HOSTED_SOURCE_READY_ABSENT_STATE_REQUIRED' USING ERRCODE='55000';
 END IF;
END $before$;
-- One completed, verified SOURCE after publication. Apply through apply.sql.
-- Provider-managed logical deletion, not proof of zero hidden provider bytes.
-- No new queue, no Storage-table writes and no fabricated auxiliary receipt.
CREATE FUNCTION listing_publication_private.hosted_completed_source_deleted_v1(p_object uuid)
RETURNS boolean LANGUAGE sql SET search_path=pg_catalog,pg_temp AS $f$
 SELECT coalesce((SELECT o.kind='source' AND o.dispatch_key IS NULL
  AND c.reason='published_source' AND c.state='deleted'
  AND c.bucket_id=o.bucket_id AND c.object_path=o.object_path
  AND m.provider_contract='supabase-s3-session-v1' AND m.state='completed'
  AND m.completed_at IS NOT NULL AND m.verified_at IS NOT NULL
  AND m.storage_object_id IS NOT NULL AND m.storage_version IS NOT NULL
  AND m.observed_sha256=encode(s.expected_source_sha256,'hex')
  AND m.observed_bytes=s.expected_source_bytes
  AND NOT EXISTS(SELECT 1 FROM listing_publication_private.hosted_storage_objects z
   WHERE z.bucket_id=o.bucket_id AND z.name=o.object_path)
  AND NOT EXISTS(SELECT 1 FROM listing_publication_private.hosted_s3_multipart_uploads u
   WHERE u.id=m.upload_id OR (u.bucket_id=o.bucket_id AND u.key=o.object_path))
  AND NOT EXISTS(SELECT 1 FROM listing_publication_private.hosted_s3_multipart_uploads_parts q
   WHERE q.upload_id=m.upload_id OR (q.bucket_id=o.bucket_id AND q.key=o.object_path))
 FROM listing_publication_private.objects o
 JOIN listing_publication_private.slots s ON s.id=o.slot_id AND s.attempt_id=o.attempt_id
 JOIN listing_publication_private.multipart_attempts a ON a.attempt_id=o.attempt_id
 JOIN listing_publication_private.multipart_sessions m ON m.object_id=o.id
 JOIN listing_publication_private.cleanup c ON c.object_id=o.id
 WHERE o.id=p_object),false);
$f$;

-- Keep the prior predicate exactly as its original alternative. The narrow new
-- SOURCE branch depends on durable lineage, never on the listing still being
-- published: later removal must not recharge an already released reservation.
CREATE OR REPLACE FUNCTION listing_publication_private.multipart_object_fully_deleted(p_id uuid)
RETURNS boolean LANGUAGE sql SET search_path=pg_catalog,pg_temp AS $f$
 SELECT listing_publication_private.hosted_completed_source_deleted_v1(p_id) OR
 (coalesce(c.state='deleted',false) AND (m.id IS NULL OR
  (EXISTS(SELECT 1 FROM listing_publication_private.multipart_auxiliary_receipts r WHERE r.session_id=m.id)
   AND NOT EXISTS(SELECT 1 FROM listing_publication_private.hosted_storage_objects z WHERE z.bucket_id=o.bucket_id AND z.name=o.object_path))))
 FROM listing_publication_private.objects o LEFT JOIN listing_publication_private.cleanup c ON c.object_id=o.id
 LEFT JOIN listing_publication_private.multipart_sessions m ON m.object_id=o.id WHERE o.id=p_id;
$f$;

CREATE FUNCTION public.claim_listing_published_source_cleanup_v1(
 p_expected_user_id uuid,p_expected_identity_id uuid,p_attempt_id uuid,p_request_key uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path=pg_catalog,pg_temp SET lock_timeout='2s' AS $f$
DECLARE aid uuid; listing_id bigint; c listing_publication_private.cleanup%ROWTYPE;
 t timestamptz:=clock_timestamp(); old_sub text:=current_setting('request.jwt.claim.sub',true);
 old_claims text:=current_setting('request.jwt.claims',true);
BEGIN
 aid:=listing_publication_private.lock_multipart_cleanup_context(
  p_expected_user_id,p_expected_identity_id,p_attempt_id,p_request_key);
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'publication_read_committed_required' USING ERRCODE='25001'; END IF;
 SELECT p.listing_id INTO listing_id FROM listing_publication_private.publications p
 JOIN listing_publication_private.attempts a ON a.id=p.attempt_id
 WHERE a.id=aid AND a.state='published' AND p.state='published' AND p.deleted_at IS NULL
 FOR SHARE OF p;
 IF NOT FOUND THEN RETURN NULL; END IF;

 -- Auth already bound this user at the server boundary. The service-only actor
 -- lock above verifies their current access. Reuse the accepted gallery checker
 -- under that same user so original identity RLS also protects its public reads.
 PERFORM set_config('request.jwt.claim.sub',p_expected_user_id::text,true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',p_expected_user_id)::text,true);
 PERFORM listing_publication_private.lock_managed_listing_images_v1(
  p_expected_user_id,p_expected_identity_id,listing_id,aid,false);
 PERFORM set_config('request.jwt.claim.sub',coalesce(old_sub,''),true);
 PERFORM set_config('request.jwt.claims',coalesce(old_claims,''),true);
 -- A failed statement/subtransaction restores its temporary GUC changes too.
 t:=clock_timestamp();

 SELECT q.* INTO c FROM listing_publication_private.cleanup q
 JOIN listing_publication_private.objects o ON o.id=q.object_id
 JOIN listing_publication_private.slots s ON s.id=o.slot_id AND s.attempt_id=o.attempt_id
 JOIN listing_publication_private.multipart_sessions m ON m.object_id=o.id
 JOIN listing_publication_private.objects w ON w.attempt_id=o.attempt_id AND w.slot_id=o.slot_id AND w.kind='web'
 JOIN listing_publication_private.web_images r ON r.attempt_id=w.attempt_id AND r.slot_id=w.slot_id
 JOIN listing_publication_private.multipart_sessions wm ON wm.object_id=w.id
 WHERE o.attempt_id=aid AND o.kind='source' AND o.dispatch_key IS NULL
  AND q.reason='published_source' AND q.bucket_id=o.bucket_id AND q.object_path=o.object_path
  AND m.provider_contract='supabase-s3-session-v1' AND m.state='completed'
  AND m.completed_at IS NOT NULL AND m.verified_at IS NOT NULL AND m.problem IS NULL
  AND m.storage_object_id IS NOT NULL AND m.storage_version IS NOT NULL
  AND m.observed_sha256=encode(s.expected_source_sha256,'hex') AND m.observed_bytes=s.expected_source_bytes
  AND listing_publication_private.object_cleanup_state(o.id)='pending'
  AND NOT EXISTS(SELECT 1 FROM listing_publication_private.hosted_s3_multipart_uploads u
   WHERE u.id=m.upload_id OR (u.bucket_id=o.bucket_id AND u.key=o.object_path))
  AND NOT EXISTS(SELECT 1 FROM listing_publication_private.hosted_s3_multipart_uploads_parts up
   WHERE up.upload_id=m.upload_id OR (up.bucket_id=o.bucket_id AND up.key=o.object_path))
  AND r.state='ready' AND r.ready_id IS NOT NULL AND r.ready_at IS NOT NULL
  AND wm.provider_contract='supabase-s3-session-v1' AND wm.state='completed'
  AND wm.completed_at IS NOT NULL AND wm.verified_at IS NOT NULL AND wm.problem IS NULL
  AND wm.observed_sha256=r.intent->>'web_sha256' AND wm.observed_bytes=(r.intent->>'web_bytes')::integer
  AND EXISTS(SELECT 1 FROM listing_publication_private.hosted_storage_objects z
   WHERE z.bucket_id=w.bucket_id AND z.name=w.object_path AND z.id=wm.storage_object_id AND z.version=wm.storage_version)
  AND NOT EXISTS(SELECT 1 FROM listing_publication_private.hosted_storage_objects z
   WHERE z.bucket_id=w.bucket_id AND z.name=w.object_path AND (z.id<>wm.storage_object_id OR z.version IS DISTINCT FROM wm.storage_version))
  AND NOT EXISTS(SELECT 1 FROM listing_publication_private.cleanup wc WHERE wc.object_id=w.id)
  AND ((q.state IN('pending','retry_wait') AND (q.not_before IS NULL OR q.not_before<=t))
   OR (q.state='in_flight' AND q.lease_until<=t))
 ORDER BY q.enqueued_at,q.object_id LIMIT 1 FOR UPDATE OF q SKIP LOCKED;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF c.try_count>=8 THEN
  UPDATE listing_publication_private.cleanup SET state='needs_attention',last_error='lease_lost' WHERE object_id=c.object_id;
  RETURN NULL;
 END IF;
 UPDATE listing_publication_private.cleanup SET state='in_flight',work_key=gen_random_uuid(),lease_until=t+interval '60 seconds',
  try_count=try_count+1,not_before=NULL,last_error=NULL WHERE object_id=c.object_id RETURNING * INTO c;
 RETURN jsonb_build_object('schema_version',1,'object_id',c.object_id,'work_key',c.work_key,'bucket_id',c.bucket_id,
  'object_path',c.object_path,'try_count',c.try_count,'lease_until_epoch',floor(extract(epoch FROM c.lease_until))::bigint);
END $f$;

CREATE FUNCTION public.record_listing_published_source_cleanup_v1(
 p_expected_user_id uuid,p_expected_identity_id uuid,p_attempt_id uuid,p_request_key uuid,
 p_object_id uuid,p_work_key uuid,p_result text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path=pg_catalog,pg_temp SET lock_timeout='2s' AS $f$
DECLARE aid uuid; result jsonb; cleanup_state text; session_problem text;
BEGIN
 aid:=listing_publication_private.lock_multipart_cleanup_context(
  p_expected_user_id,p_expected_identity_id,p_attempt_id,p_request_key);
 -- A listing may be removed after the external DELETE was dispatched. Preserve
 -- the original published_source lineage; do not require mutable published state.
 SELECT c.state,m.problem INTO cleanup_state,session_problem FROM listing_publication_private.objects o
 JOIN listing_publication_private.cleanup c ON c.object_id=o.id
 JOIN listing_publication_private.multipart_sessions m ON m.object_id=o.id
 WHERE o.id=p_object_id AND o.attempt_id=aid AND o.kind='source' AND o.dispatch_key IS NULL
  AND c.reason='published_source' AND c.bucket_id=o.bucket_id AND c.object_path=o.object_path
  AND c.work_key=p_work_key AND m.state='completed' AND m.completed_at IS NOT NULL AND m.verified_at IS NOT NULL
 FOR UPDATE OF c;
 IF NOT FOUND THEN RAISE EXCEPTION 'publication_source_cleanup_binding' USING ERRCODE='42501'; END IF;
 IF p_result='deleted' AND cleanup_state<>'deleted' AND session_problem IS NOT NULL THEN
  RAISE EXCEPTION 'publication_source_cleanup_not_observed' USING ERRCODE='55000';
 END IF;
 -- A later diagnostic cannot undo an already accepted logical deletion. The
 -- immutable verified lineage and current metadata absence remain mandatory.
 -- The closed recorder owns lease expiry, idempotency, backoff and retry limits.
 result:=public.record_listing_cleanup_v1(p_object_id,p_work_key,p_result);
 IF p_result='deleted' AND listing_publication_private.hosted_completed_source_deleted_v1(p_object_id) IS DISTINCT FROM true THEN
  RAISE EXCEPTION 'publication_source_cleanup_not_observed' USING ERRCODE='55000';
 END IF;
 -- Failure above rolls back the recorder update; no quota changes on an ACK alone.
 RETURN result;
END $f$;

GRANT CREATE ON SCHEMA public TO selqiro_listing_final_writer_v1;
ALTER FUNCTION public.claim_listing_published_source_cleanup_v1(uuid,uuid,uuid,uuid) OWNER TO selqiro_listing_final_writer_v1;
ALTER FUNCTION public.record_listing_published_source_cleanup_v1(uuid,uuid,uuid,uuid,uuid,uuid,text) OWNER TO selqiro_listing_final_writer_v1;
REVOKE CREATE ON SCHEMA public FROM selqiro_listing_final_writer_v1;
REVOKE ALL ON FUNCTION listing_publication_private.hosted_completed_source_deleted_v1(uuid),
 public.claim_listing_published_source_cleanup_v1(uuid,uuid,uuid,uuid),
 public.record_listing_published_source_cleanup_v1(uuid,uuid,uuid,uuid,uuid,uuid,text)
 FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION listing_publication_private.hosted_completed_source_deleted_v1(uuid)
 TO selqiro_listing_final_writer_v1;
GRANT EXECUTE ON FUNCTION public.claim_listing_published_source_cleanup_v1(uuid,uuid,uuid,uuid),
 public.record_listing_published_source_cleanup_v1(uuid,uuid,uuid,uuid,uuid,uuid,text) TO service_role;
COMMENT ON FUNCTION listing_publication_private.hosted_completed_source_deleted_v1(uuid) IS
 'Hosted logical SOURCE removal after confirmed Complete/verification and Storage API delete. Provider owns hidden temporary-part lifecycle; no physical disk-zero or local process-exit evidence is claimed.';

CREATE TEMP TABLE hosted_source_install_after ON COMMIT DROP AS WITH function_facts AS (SELECT n.nspname||'.'||p.proname name,
 format('%I.%I(%s)',n.nspname,p.proname,oidvectortypes(p.proargtypes)) signature,
 jsonb_build_object('definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),
 'language',l.lanname,'kind',p.prokind,'leakproof',p.proleakproof,'parallel',p.proparallel) facts,
 (SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(x.grantor),
 'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,
 'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY x.grantee::regrole::text,x.privilege_type,x.is_grantable),'[]')
 FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x) acl
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang
 WHERE p.prokind='f' AND (n.nspname='listing_publication_private' OR n.nspname||'.'||p.proname=ANY(ARRAY['public.current_user_has_identity_access','public.set_listing_primary_image_v2','public.listing_actor_uid_hosted_v1','listing_publication_private.hosted_storage_contract_ready','listing_publication_private.assert_hosted_preview_actor','public.lock_listing_creation_actor_v1','public.require_listing_create_keys_v1','listing_publication_private.require_actor','listing_publication_private.validate_web_intent','public.listing_final_guard_state_v1','public.guard_listing_price_v2','listing_publication_private.guard_managed_listing','listing_publication_private.guard_managed_image','listing_publication_private.protect_attempt','listing_publication_private.protect_slot','listing_publication_private.protect_object','listing_publication_private.protect_web_image','listing_publication_private.protect_publication','listing_publication_private.apply_delete','listing_publication_private.final_receipt','public.delete_my_published_listing_v1','public.get_selqiro_hosted_preview_readiness_v1','listing_publication_private.require_upload_service','listing_publication_private.lock_upload_service_actor','listing_publication_private.lock_multipart_cleanup_context','listing_publication_private.legacy_cleanup_state_before_multipart_v2','listing_publication_private.object_cleanup_state','listing_publication_private.protect_cleanup','listing_publication_private.protect_multipart_attempt','listing_publication_private.protect_multipart_session','listing_publication_private.protect_multipart_auxiliary','listing_publication_private.protect_multipart_abort','listing_publication_private.guard_legacy_source_in_multipart','public.claim_listing_cleanup_v1','public.record_listing_cleanup_v1','public.claim_listing_cleanup_for_attempt_v2','public.get_my_listing_cleanup_summary_v1','listing_publication_private.require_managed_image_actor_v1','listing_publication_private.validate_managed_image_intent_v1','listing_publication_private.lock_managed_listing_images_v1','listing_publication_private.hosted_completed_source_deleted_v1','public.claim_listing_published_source_cleanup_v1','public.record_listing_published_source_cleanup_v1','listing_publication_private.multipart_object_fully_deleted']::text[]))),
 relation_facts AS (SELECT n.nspname||'.'||c.relname name,
 jsonb_build_object('name',n.nspname||'.'||c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),
 'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'persistence',c.relpersistence,
 'columns',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),
 'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,
 'default',pg_get_expr(ad.adbin,ad.adrelid),'collation',CASE WHEN a.attcollation=0 THEN NULL ELSE a.attcollation::regcollation::text END)
 ORDER BY a.attnum),'[]') FROM pg_attribute a LEFT JOIN pg_attrdef ad ON ad.adrelid=a.attrelid AND ad.adnum=a.attnum
 WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',q.conname,'type',q.contype,
 'definition',pg_get_constraintdef(q.oid),'validated',q.convalidated,'deferrable',q.condeferrable,'deferred',q.condeferred,
 'local',q.conislocal,'inheritance',q.coninhcount,'no_inherit',q.connoinherit) ORDER BY q.conname),'[]')
 FROM pg_constraint q WHERE q.conrelid=c.oid AND q.contype<>'n'),
 'nonstandard_not_null',(SELECT count(*) FROM pg_constraint q WHERE q.conrelid=c.oid AND q.contype='n'
 AND (NOT q.convalidated OR NOT q.conislocal OR q.coninhcount<>0 OR q.connoinherit)),
 'inheritance',(SELECT coalesce(jsonb_agg(i.inhparent::regclass::text ORDER BY i.inhseqno),'[]') FROM pg_inherits i WHERE i.inhrelid=c.oid),
 'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',ic.relname,'definition',pg_get_indexdef(i.indexrelid),
 'valid',i.indisvalid,'ready',i.indisready) ORDER BY ic.relname),'[]') FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=c.oid),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,
 'definition',pg_get_triggerdef(t.oid)) ORDER BY t.tgname),'[]') FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal)) structure,
 jsonb_build_object('acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(x.grantor),
 'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'privilege',x.privilege_type,'grantable',x.is_grantable)
 ORDER BY x.grantee::regrole::text,x.privilege_type,x.is_grantable),'[]') FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x),
 'column_acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('column',a.attname,'grantor',pg_get_userbyid(x.grantor),
 'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'privilege',x.privilege_type,'grantable',x.is_grantable)
 ORDER BY a.attname,x.grantee::regrole::text,x.privilege_type),'[]') FROM pg_attribute a CROSS JOIN LATERAL aclexplode(a.attacl) x
 WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'policies',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',q.polname,'permissive',q.polpermissive,'command',q.polcmd,
